// ===== CONTROL PANEL =====
const CONFIG = { dryRun: true, maxPerCycle: 1, minAgeMin: 3, windowH: 24,
                 days: [0,1,2,3,4,5,6], startHour: 0, endHour: 24, tz: 'Europe/London' };
// =========================
// dryRun ships true. Read 20-30 drafts in the execution log, tune the SOP text,
// then flip it. minAgeMin exists because a lead often sends three messages in a
// row: replying to the first one makes the setter look like a bot.

const EXCLUDE_CONTACT_IDS = [];   // TODO: Prince + the MadeEA team (must match the follow-up's list)
const EXCLUDE_NAMES = ["ai chat", "chat ai", "chat al"];

const localNow = new Date(new Date().toLocaleString('en-US', { timeZone: CONFIG.tz }));
const daytime = CONFIG.days.includes(localNow.getDay())
  && localNow.getHours() >= CONFIG.startHour && localNow.getHours() < CONFIG.endHour;
if (!daytime) return [];   // hard stop outside the sending window

const sd = $getWorkflowStaticData('global');
sd.handled = sd.handled || {};

const convs = ($input.first().json.conversations) || [];
const out = [];
for (const c of convs) {
  if (c.lastMessageType !== 'TYPE_INSTAGRAM') continue;
  if (c.lastMessageDirection !== 'inbound') continue;          // they must have spoken last
  if (EXCLUDE_CONTACT_IDS.includes(c.contactId)) continue;
  const name = (c.contactName || c.fullName || '').toLowerCase();
  if (EXCLUDE_NAMES.some(b => name.includes(b))) continue;

  const last = Number(c.lastMessageDate || 0);
  if (!last) continue;
  const ageMin = (Date.now() - last) / 60000;
  if (ageMin < CONFIG.minAgeMin) continue;                     // let them finish typing
  if (ageMin / 60 >= CONFIG.windowH) continue;                 // outside IG's 24h window: undeliverable

  // Keyed by the message we answered, not the conversation: a NEW inbound message
  // must reopen a thread we already replied to, or the setter answers once and
  // goes permanently deaf.
  if (sd.handled[c.id] === last) continue;

  out.push({ json: {
    conversationId: c.id,
    contactId: c.contactId,
    contactName: c.contactName || c.fullName || c.id,
    lastMessageDate: last,
    dryRun: CONFIG.dryRun,
  }});
}
return out.slice(0, CONFIG.maxPerCycle);

// Every guardrail lives here. A draft that trips one is HELD for a human rather
// than softened: a message that had to be rewritten to be safe is a message the
// brain got wrong, and quietly patching it hides that.

function hasPlaceholder(s) {
  const t = String(s);
  if (/\[[^\]]*\]|\{\{|\}\}|<[a-z_]+>/i.test(t)) return true;
  if (/\b(your business name|business name here|their name|insert |name here|first name)\b/i.test(t)) return true;
  return false;
}
function oneMarker(s) {
  const RE = /([\u{1F000}-\u{1FAFF}\u{2600}-\u{27BF}\u{2300}-\u{23FF}\u{2B00}-\u{2BFF}]\u{FE0F}?|:-?\)|:-?\(|;-?\)|:D)/gu;
  let n = 0;
  return s.replace(RE, m => (++n === 1 ? m : '')).replace(/ {2,}/g, ' ').replace(/\s+([.!?,])/g, '$1').trim();
}
function stripControl(s) {
  s = s.replace(/<(\w+:[\w:]+)>[\s\S]*?<\/\1>/g, '');
  s = s.replace(/<budget:[\s\S]*$/i, '');
  s = s.replace(/<\/?\w+:[\w:.\-]*[^>]*>/g, '');
  return s.replace(/\s*[\u2014\u2013]\s*/g, ', ').replace(/[ \t]{2,}/g, ' ').trim();
}
// SOP non-negotiable #5. One wrong noun puts MadeEA in the category the whole
// SOP exists to escape, so this is a hold, not a rewrite.
function isBannedCategory(s) {
  const t = String(s).toLowerCase();
  if (/\bv\.?a\.?s?\b/.test(t) && !/\bvalue\b/.test(t)) return true;
  if (/\bvirtual assistants?\b/.test(t)) return true;
  if (/\b(outsourc|offshor)(e|ed|ing)\b/.test(t)) return true;
  return false;
}
// SOP Fact Pack: $3,000/month and from $2,250/month are the only figures that exist.
// Pricing is ALLOWED here (the SOP publishes it) — this caps which numbers, not the topic.
function isUnapprovedPrice(s) {
  const APPROVED = /^(3,?000|3k|2,?250)$/i;
  const nums = String(s).match(/(?:\$|usd\s*|\u00a3|\u20ac)\s?([\d,]+(?:\.\d+)?k?)/gi) || [];
  for (const n of nums) {
    if (!APPROVED.test(n.replace(/[^\d,.k]/gi, ''))) return true;
  }
  if (/\b\d{1,2}\s?%\s?(off|discount)\b/i.test(String(s))) return true;
  return false;
}
// SOP non-negotiable #4: max 2 sentences, unless it is quoting the tiers.
// Fragments must contain a letter to count. The splitter breaks after "?", so a
// trailing emoji would otherwise register as a phantom third sentence — and the
// SOP explicitly allows one emoji in Phases 1 and 5, so that mis-hold would have
// caught a large share of legitimate openers and invites.
function isTooLong(s) {
  if (/\$\s?(3,?000|2,?250)/i.test(s)) return false;
  return String(s).split(/(?<=[.!?])\s+/).filter(x => /[a-z]/i.test(x)).length > 2;
}
function isIdentityLeak(s) {
  return /\b(as an ai|i am an ai|i'm an ai|language model|chatbot|automated assistant)\b/i.test(String(s));
}
// Never claim an action the workflow cannot perform: it sends DMs, nothing else.
function isFalsePromise(s) {
  return /\b(just (sent|emailed|shared)|i('ve| have) (sent|emailed|attached|booked)|sending (it|that) (over|now)|added you to)\b/i.test(String(s));
}

const reqs = $('Build LLM Request').all();
const ors = $input.all();
const out = [];

for (let i = 0; i < ors.length; i++) {
  const ctx = reqs[i].json;
  const r = ors[i].json;
  const base = { conversationId: ctx.conversationId, contactId: ctx.contactId,
                 contactName: ctx.contactName, lastMessageDate: ctx.lastMessageDate, dryRun: ctx.dryRun };

  let draft = (Array.isArray(r.content) ? r.content.filter(b => b && b.type === 'text').map(b => b.text).join('') : '').trim();
  if (!draft) continue;

  // The four silent exits: tag it so the team can see WHY the bot went quiet,
  // then send nothing.
  const exits = { '<SKIP>': 'madeea-setter-not-a-fit', '<HOLD>': 'madeea-setter-deciding',
                  '<NOTREADY>': 'madeea-setter-not-ready', '<HANDOFF>': 'madeea-setter-needs-human' };
  const hit = Object.keys(exits).find(t => new RegExp('^' + t.replace(/[<>]/g, m => '\\' + m), 'i').test(draft));
  if (hit) { out.push({ json: { ...base, hold: true, tag: exits[hit], reason: hit } }); continue; }

  draft = oneMarker(stripControl(draft.replace(/\s*\n+\s*/g, '\n')));
  if (!draft) continue;

  const failed = hasPlaceholder(draft) ? 'placeholder'
    : isBannedCategory(draft) ? 'banned-category'
    : isUnapprovedPrice(draft) ? 'unapproved-price'
    : isTooLong(draft) ? 'too-long'
    : isIdentityLeak(draft) ? 'identity-leak'
    : isFalsePromise(draft) ? 'false-promise'
    : null;
  if (failed) { out.push({ json: { ...base, hold: true, tag: 'madeea-setter-needs-human', reason: failed, draft } }); continue; }

  // Two bubbles read like a person thinking; three reads like a script.
  const parts = draft.split('\n').map(s => s.trim()).filter(Boolean);
  const bubbles = (parts.length > 1 ? parts : [draft]).slice(0, 2);

  const askedPrice = /\$\s?(3,?000|2,?250)/i.test(draft);
  out.push({ json: { ...base, hold: false, bubbles,
    tag: askedPrice ? 'madeea-setter-pricing-asked' : 'madeea-setter-engaged' } });
}
return out;

// Did they write again while the model was thinking? If so our draft answers a
// message that is no longer the last one, and sending it makes the setter look
// like it is talking past them. Drop it: the next cycle picks the thread up with
// the newer message included.
const ctxs = $('Extract Draft').all().filter(it => !it.json.hold);
const convs = $input.all();
const out = [];
for (let i = 0; i < convs.length; i++) {
  const ctx = ctxs[i].json;
  const c = convs[i].json.conversation || convs[i].json;
  const latest = Number(c.lastMessageDate || 0);
  if (latest && latest > Number(ctx.lastMessageDate)) continue;
  out.push({ json: ctx });
}
return out;

// n8n credentials are not reachable from this.helpers.httpRequest, so the token
// is a constant. Fill it in inside n8n and do not commit the filled-in file.
const TOKEN = 'REPLACE_WITH_MADEEA_GHL_PRIVATE_INTEGRATION_TOKEN';
const GAP_MS = 4000;   // human typing rhythm between bubbles

const out = [];
for (const item of $input.all()) {
  const j = item.json;
  const sent = [];
  for (let i = 0; i < j.bubbles.length; i++) {
    if (i > 0) await new Promise(r => setTimeout(r, GAP_MS));
    try {
      await this.helpers.httpRequest({
        method: 'POST',
        url: 'https://services.leadconnectorhq.com/conversations/messages',
        headers: { Authorization: 'Bearer ' + TOKEN, Version: '2021-07-28', 'Content-Type': 'application/json' },
        body: { type: 'IG', contactId: j.contactId, message: j.bubbles[i] },
        json: true,
      });
      sent.push(j.bubbles[i]);
    } catch (e) {
      // Stop at the first failure: bubble 2 without bubble 1 is worse than silence.
      out.push({ json: { ...j, sent, error: String(e && e.message || e) } });
      break;
    }
  }
  if (sent.length === j.bubbles.length) out.push({ json: { ...j, sent } });
}
return out;

// Key on the message we answered, so a NEW inbound message reopens the thread.
const sd = $getWorkflowStaticData('global');
sd.handled = sd.handled || {};
for (const item of $input.all()) {
  if (!item.json.dryRun) sd.handled[item.json.conversationId] = item.json.lastMessageDate;
}
return $input.all();
